/// Printed verbatim in text and JSON output so no reader can mistake the provenance.
inline constexpr std::string_view kSyntheticDisclaimer =
    "Populations are SYNTHETIC (logical profiles generated by SyntheticLaboratory from "
    "an explicit seed). This is a single-process, in-memory measurement. No multi-node "
    "or multi-GPU claim is implied or measured, and no physical scale is claimed.";
inline constexpr std::string_view kNoTimeoutDisclaimer =
    "No timeouts are used: no CTest TIMEOUT, no shell wrapper, no watchdog. Every "
    "benchmark runs to completion naturally; only a correctness guard failure produces "
    "a non-zero exit code.";

/// Fixed 2-decimal formatting. Non-finite values are reported as zero rather than as
/// an invented or non-JSON literal.
[[nodiscard]] inline std::string format_fixed(double value, int decimals = 2) {
  if (!std::isfinite(value)) {
    return decimals == 2 ? std::string("0.00") : std::string("0");
  }
  char buffer[64] = {};
  const int written = std::snprintf(buffer, sizeof(buffer), "%.*f", decimals, value);
  if (written <= 0) {
    return decimals == 2 ? std::string("0.00") : std::string("0");
  }
  return std::string(buffer);
}

/// Throughput of completed operations. Zero completed operations or a non-positive
/// elapsed time yields 0.00 rather than a fabricated rate.
[[nodiscard]] inline double ops_per_second(std::uint64_t operations, double elapsed_ms) {
  if (operations == 0 || !(elapsed_ms > 0.0)) {
    return 0.0;
  }
  return static_cast<double>(operations) * 1000.0 / elapsed_ms;
}

/// Monotonic wall-clock timer. Only elapsed durations are reported; no wall-clock
/// timestamps enter the output.
class Stopwatch {
 public:
  Stopwatch() noexcept : start_(std::chrono::steady_clock::now()) {}
  void restart() noexcept { start_ = std::chrono::steady_clock::now(); }
  [[nodiscard]] double elapsed_ms() const noexcept {
    return std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start_).count();
  }

 private:
  std::chrono::steady_clock::time_point start_;
};

/// One reported benchmark row. `operations` is always a count of COMPLETED
/// operations, never an enqueue or request count.
struct Measurement {
  std::string operation;
  std::string unit;
  std::uint64_t operations{0};
  double elapsed_ms{0.0};
  double ops_per_second{0.0};
  bool completed{false};
  std::string failure;
  std::string detail;
};

/// Finalizes a row: derives throughput and completion state from real counts.
inline void finish_row(Measurement& row) {
  row.ops_per_second = ops_per_second(row.operations, row.elapsed_ms);
  row.completed = row.operations > 0 && row.failure.empty();
}

struct SkippedScale {
  std::uint32_t agents{0};
  std::uint32_t work{0};
  std::uint64_t candidate_evaluations{0};
  std::string reason;
};

struct ScaleReport {
  std::uint32_t agents{0};
  std::uint32_t work{0};
  std::uint32_t rounds{0};
  std::uint64_t seed{0};
  std::uint64_t candidate_evaluations{0};
  std::uint64_t schedule_batch_calls{0};
  std::uint64_t decisions{0};
  std::uint64_t eligible_candidates{0};
  std::uint64_t factor_scores{0};
  std::uint64_t assignments_committed{0};
  std::uint64_t assignments_released{0};
  std::uint64_t snapshots{0};
  std::uint64_t invariant_reports{0};
  std::uint64_t bytes_written{0};
  std::vector<Measurement> rows;
  std::vector<std::string> notes;
};

struct BenchReport {
  std::string mode;
  std::uint64_t seed{0};
  std::uint32_t rounds{0};
  std::uint64_t candidate_budget{0};
  std::vector<ScaleReport> scales;
  std::vector<SkippedScale> skipped;
  std::vector<std::string> guard_failures;

  [[nodiscard]] bool guards_clean() const noexcept { return guard_failures.empty(); }

  /// Non-zero when any guard tripped or any measured row completed zero operations.
  [[nodiscard]] int exit_code() const noexcept {
    if (!guards_clean()) {
      return 1;
    }
    for (const ScaleReport& scale : scales) {
      for (const Measurement& row : scale.rows) {
        if (!row.completed) {
          return 1;
        }
      }
    }
    return 0;
  }
};

/// Collects correctness-guard failures. Guards never abort the run: the suite always
/// finishes, then reports every failure and exits non-zero.
class GuardLog {
 public:
  void check(bool condition, std::string message) {
    if (!condition) {
      failures_.push_back(std::move(message));
    }
  }
  void fail(std::string message) { failures_.push_back(std::move(message)); }
  [[nodiscard]] bool clean() const noexcept { return failures_.empty(); }
  [[nodiscard]] const std::vector<std::string>& failures() const noexcept { return failures_; }

 private:
  std::vector<std::string> failures_;
};

struct CliOptions {
  std::uint32_t agents{0};
  std::uint32_t work{0};
  std::uint32_t rounds{3};
  std::uint64_t seed{20260910};
  std::uint64_t candidate_budget{12000000};
  bool json{false};
  bool quick{false};
  bool help{false};
  bool version{false};
  std::string error;
};

[[nodiscard]] inline std::string usage_text() {
  return std::string(
      "agent_scheduler_bench - Agent Scheduler benchmark suite\n"
      "\n"
      "Populations are SYNTHETIC (logical profiles from SyntheticLaboratory with an\n"
      "explicit seed). Single-process, in-memory measurement. No multi-node or\n"
      "multi-GPU claim is implied. No timeouts are used; every benchmark runs to\n"
      "completion naturally. Exit code 0 on success, 1 if any correctness guard\n"
      "trips or any measured operation count is zero.\n"
      "\n"
      "Usage: agent_scheduler_bench [options]\n"
      "\n"
      "  --agents N            run a single scale with N synthetic agents\n"
      "                        (omitted: run the ladder over agents 10/100/1000/10000)\n"
      "  --work M              run a single scale with M synthetic work items\n"
      "                        (omitted: run the ladder over work 1000/10000/100000)\n"
      "  --rounds R            scheduling rounds per scale (default 3)\n"
      "  --seed S              synthetic population seed (default 20260910)\n"
      "  --candidate-budget B  maximum candidate evaluations per scheduling pass;\n"
      "                        scales above it are skipped with a printed reason\n"
      "                        (default 12000000)\n"
      "  --json                emit deterministic JSON (JsonWriter) instead of text\n"
      "  --quick               small ladder: agents 10/100 with work 1000\n"
      "  --help                print this help and exit 0\n"
      "  --version             print the version and exit 0\n");
}

[[nodiscard]] inline bool parse_u64(std::string_view text, std::uint64_t& out) {
  if (text.empty()) {
    return false;
  }
  for (const char character : text) {
    if (character < '0' || character > '9') {
      return false;
    }
  }
  errno = 0;
  const std::string owned(text);
  char* end = nullptr;
  const unsigned long long value = std::strtoull(owned.c_str(), &end, 10);
  if (errno != 0 || end == nullptr || *end != '\0') {
    return false;
  }
  out = static_cast<std::uint64_t>(value);
  return true;
}

/// Parses `--flag value` and `--flag=value` forms. Unknown flags and malformed
/// values are reported in CliOptions::error; nothing prompts and nothing exits here.
[[nodiscard]] inline CliOptions parse_cli(int argc, char** argv) {
  CliOptions options;
  for (int index = 1; index < argc; ++index) {
    std::string argument = argv[index] == nullptr ? std::string() : std::string(argv[index]);
    std::string value;
    const std::size_t equals = argument.find('=');
    if (equals != std::string::npos) {
      value = argument.substr(equals + 1);
      argument = argument.substr(0, equals);
    }
    const auto take_value = [&](std::uint64_t& target) {
      if (!value.empty()) {
        return parse_u64(value, target);
      }
      if (index + 1 >= argc || argv[index + 1] == nullptr) {
        return false;
      }
      ++index;
      return parse_u64(std::string_view(argv[index]), target);
    };
    if (argument == "--help" || argument == "-h") {
      options.help = true;
    } else if (argument == "--version") {
      options.version = true;
    } else if (argument == "--json") {
      options.json = true;
    } else if (argument == "--quick") {
      options.quick = true;
    } else if (argument == "--agents") {
      std::uint64_t parsed = 0;
      if (!take_value(parsed) || parsed == 0 || parsed > 200000) {
        options.error = "--agents requires an integer in [1, 200000]";
        return options;
      }
      options.agents = static_cast<std::uint32_t>(parsed);
    } else if (argument == "--work") {
      std::uint64_t parsed = 0;
      if (!take_value(parsed) || parsed == 0 || parsed > 500000) {
        options.error = "--work requires an integer in [1, 500000]";
        return options;
      }
      options.work = static_cast<std::uint32_t>(parsed);
    } else if (argument == "--rounds") {
      std::uint64_t parsed = 0;
      if (!take_value(parsed) || parsed == 0 || parsed > 1000) {
        options.error = "--rounds requires an integer in [1, 1000]";
        return options;
      }
      options.rounds = static_cast<std::uint32_t>(parsed);
    } else if (argument == "--seed") {
      std::uint64_t parsed = 0;
      if (!take_value(parsed)) {
        options.error = "--seed requires a non-negative integer";
        return options;
      }
      options.seed = parsed;
    } else if (argument == "--candidate-budget") {
      std::uint64_t parsed = 0;
      if (!take_value(parsed) || parsed == 0) {
        options.error = "--candidate-budget requires a positive integer";
        return options;
      }
      options.candidate_budget = parsed;
    } else {
      options.error = "unknown argument: " + argument;
      return options;
    }
  }
  return options;
}

[[nodiscard]] inline std::string pad_right(std::string text, std::size_t width) {
  if (text.size() < width) {
    text.append(width - text.size(), ' ');
  }
  return text;
}

[[nodiscard]] inline std::string pad_left(std::string text, std::size_t width) {
  if (text.size() < width) {
    text.insert(text.begin(), width - text.size(), ' ');
  }
  return text;
}

/// Deterministic text rendering. Column widths are derived from the content, so the
/// same counts always produce the same layout.
[[nodiscard]] inline std::string render_text(const BenchReport& report) {
  std::size_t label_width = 24;
  for (const ScaleReport& scale : report.scales) {
    for (const Measurement& row : scale.rows) {
      label_width = row.operation.size() > label_width ? row.operation.size() : label_width;
    }
  }
  std::string out;
  out += "Agent Scheduler benchmark suite ";
  out += std::string(agent_scheduler::version_string);
  out += "\n";
  out += "mode=" + report.mode + " seed=" + std::to_string(report.seed) +
         " rounds=" + std::to_string(report.rounds) +
         " candidate_budget=" + std::to_string(report.candidate_budget) + "\n";
  out += std::string(kSyntheticDisclaimer) + "\n";
  out += std::string(kNoTimeoutDisclaimer) + "\n";
  out += "\n";
  if (!report.skipped.empty()) {
    out += "SKIPPED SCALES (explicit, never silent):\n";
    for (const SkippedScale& skipped : report.skipped) {
      out += "  SKIPPED agents=" + std::to_string(skipped.agents) + " work=" + std::to_string(skipped.work) +
             ": " + std::to_string(skipped.candidate_evaluations) + " candidate evaluations exceed the budget " +
             std::to_string(report.candidate_budget) + "\n";
    }
    out += "\n";
  }
  std::size_t index = 0;
  for (const ScaleReport& scale : report.scales) {
    ++index;
    out += "=== scale " + std::to_string(index) + "/" + std::to_string(report.scales.size()) +
           ": agents=" + std::to_string(scale.agents) + " work=" + std::to_string(scale.work) +
           " rounds=" + std::to_string(scale.rounds) + " seed=" + std::to_string(scale.seed) + " ===\n";
    out += pad_right("operation", label_width + 2) + pad_left("completed_ops", 14) + pad_left("elapsed_ms", 13) +
           pad_left("ops/sec", 17) + "\n";
    for (const Measurement& row : scale.rows) {
      out += pad_right(row.operation, label_width + 2) + pad_left(std::to_string(row.operations), 14) +
             pad_left(format_fixed(row.elapsed_ms), 13) + pad_left(format_fixed(row.ops_per_second), 17) + "\n";
      if (!row.detail.empty()) {
        out += std::string(label_width + 2, ' ') + "  detail: " + row.detail + "\n";
      }
      if (!row.failure.empty()) {
        out += std::string(label_width + 2, ' ') + "  FAILED: " + row.failure + "\n";
      }
    }
    out += "  totals: schedule_batch_calls=" + std::to_string(scale.schedule_batch_calls) +
           " decisions=" + std::to_string(scale.decisions) +
           " candidates_examined=" + std::to_string(scale.candidate_evaluations) +
           " eligible_candidates=" + std::to_string(scale.eligible_candidates) +
           " factor_scores=" + std::to_string(scale.factor_scores) +
           " assignments_committed=" + std::to_string(scale.assignments_committed) +
           " assignments_released=" + std::to_string(scale.assignments_released) +
           " snapshots=" + std::to_string(scale.snapshots) +
           " invariant_reports=" + std::to_string(scale.invariant_reports) +
           " bytes_written=" + std::to_string(scale.bytes_written) + "\n";
    for (const std::string& note : scale.notes) {
      out += "  note: " + note + "\n";
    }
    out += "\n";
  }
  if (!report.guards_clean()) {
    out += "CORRECTNESS GUARDS: " + std::to_string(report.guard_failures.size()) + " FAILURE(S)\n";
    for (const std::string& failure : report.guard_failures) {
      out += "  GUARD FAILURE: " + failure + "\n";
    }
  } else {
    out += "CORRECTNESS GUARDS: clean\n";
  }
  out += "exit_code=" + std::to_string(report.exit_code()) + "\n";
  return out;
}

/// Deterministic JSON rendering through agent_scheduler::JsonWriter. Keys are emitted
/// in a fixed canonical order; doubles are emitted with exactly two decimals.
[[nodiscard]] inline std::string render_json(const BenchReport& report) {
  agent_scheduler::JsonWriter writer;
  writer.begin_object();
  writer.key("suite").value("agent_scheduler_bench");
  writer.key("version").value(std::string_view(agent_scheduler::version_string));
  writer.key("mode").value(report.mode);
  writer.key("seed").value(report.seed);
  writer.key("rounds").value(static_cast<std::uint64_t>(report.rounds));
  writer.key("candidate_budget").value(report.candidate_budget);
  writer.key("population").value("synthetic-logical-profiles");
  writer.key("measurement").value("single-process-in-memory");
  writer.key("notes");
  writer.begin_array();
  writer.value(kSyntheticDisclaimer);
  writer.value(kNoTimeoutDisclaimer);
  writer.end_array();
  writer.key("skipped_scales");
  writer.begin_array();
  for (const SkippedScale& skipped : report.skipped) {
    writer.begin_object();
    writer.key("agents").value(static_cast<std::uint64_t>(skipped.agents));
    writer.key("work").value(static_cast<std::uint64_t>(skipped.work));
    writer.key("candidate_evaluations").value(skipped.candidate_evaluations);
    writer.key("reason").value(skipped.reason);
    writer.end_object();
  }
  writer.end_array();
  writer.key("scales");
  writer.begin_array();
  for (const ScaleReport& scale : report.scales) {
    writer.begin_object();
    writer.key("agents").value(static_cast<std::uint64_t>(scale.agents));
    writer.key("work").value(static_cast<std::uint64_t>(scale.work));
    writer.key("rounds").value(static_cast<std::uint64_t>(scale.rounds));
    writer.key("seed").value(scale.seed);
    writer.key("schedule_batch_calls").value(scale.schedule_batch_calls);
    writer.key("decisions").value(scale.decisions);
    writer.key("candidates_examined").value(scale.candidate_evaluations);
    writer.key("eligible_candidates").value(scale.eligible_candidates);
    writer.key("factor_scores").value(scale.factor_scores);
    writer.key("assignments_committed").value(scale.assignments_committed);
    writer.key("assignments_released").value(scale.assignments_released);
    writer.key("snapshots").value(scale.snapshots);
    writer.key("invariant_reports").value(scale.invariant_reports);
    writer.key("bytes_written").value(scale.bytes_written);
    writer.key("rows");
    writer.begin_array();
    for (const Measurement& row : scale.rows) {
      writer.begin_object();
      writer.key("operation").value(row.operation);
      writer.key("unit").value(row.unit);
      writer.key("completed_operations").value(row.operations);
      writer.key("elapsed_ms").raw(format_fixed(row.elapsed_ms));
      writer.key("ops_per_second").raw(format_fixed(row.ops_per_second));
      writer.key("completed").value(row.completed);
      writer.key("detail").value(row.detail);
      writer.key("failure").value(row.failure);
      writer.end_object();
    }
    writer.end_array();
    writer.key("notes");
    writer.begin_array();
    for (const std::string& note : scale.notes) {
      writer.value(note);
    }
    writer.end_array();
    writer.end_object();
  }
  writer.end_array();
  writer.key("guard_failures");
  writer.begin_array();
  for (const std::string& failure : report.guard_failures) {
    writer.value(failure);
  }
  writer.end_array();
  writer.key("guards_clean").value(report.guards_clean());
  writer.key("exit_code").value(static_cast<std::int64_t>(report.exit_code()));
  writer.end_object();
  return writer.str();
}

